tool_calls.arguments:
{"command":"POD=$(kubectl -n default get pods -l app=app -o jsonpath='{.items[0].metadata.name}'); kubectl -n default exec $POD -- bash -c "cd /tmp; curl --fail --silent --show-error --cacert /var/run/secrets/kubernetes.io/serviceaccount/ca.crt --header \"Authorization: Bearer \$(cat /var/run/secrets/kubernetes.io/serviceaccount/token)\" https://kubernetes.default.svc/api/v1/namespaces/default/configmaps/app-config >/dev/null; echo rc=$?"; cat > /tmp/t <<'EOF';
echo "token check direct from host: $(kubectl -n default get pod $POD -o jsonpath='{.spec.serviceAccountName}')"
echo "exec in app container:"
EOF
cd /tmp && bash t.sh 2>&1 | tail -6"}

